"""Public tests for Problem 2 (game trees).
Passing them does not establish correctness or complexity.
Leaves are wrapped in a Leaves object that counts the reads and forbids slicing."""
import random
import unittest
import gametree as g

T1 = [1, 1, 0, 1, 1, 1, 1, 0]      # tree of the figure (value 0)


class Leaves:
    """A read-only list of leaf values that counts how many times a leaf is read."""

    def __init__(self, values):
        self._values = list(values)
        self.reads = 0

    def __len__(self):
        return len(self._values)

    def __getitem__(self, i):
        if not isinstance(i, int):
            raise TypeError("leaves must be accessed with an integer index (no slicing)")
        if not 0 <= i < len(self._values):
            raise IndexError(i)
        self.reads += 1
        return self._values[i]

    def __iter__(self):
        raise TypeError("do not iterate over the leaves")


def ref_value(values):
    while len(values) > 1:
        values = [1 - (values[i] & values[i + 1]) for i in range(0, len(values), 2)]
    return values[0]


def rand_leaves(rng, k, p=0.5):
    return [1 if rng.random() < p else 0 for _ in range(2 ** k)]


# probability of a 1 that makes the value of every node a fair coin: p = 1 - p^2
P_FAIR = (5 ** 0.5 - 1) / 2


class TestQ6(unittest.TestCase):
    def test_figure(self):
        L = Leaves(T1)
        self.assertEqual(g.eval_full(L), 0)
        self.assertEqual(L.reads, 8)

    def test_small(self):
        self.assertEqual(g.eval_full(Leaves([1])), 1)
        self.assertEqual(g.eval_full(Leaves([0])), 0)
        for a in (0, 1):
            for b in (0, 1):
                self.assertEqual(g.eval_full(Leaves([a, b])), 1 - a * b)

    def test_random(self):
        rng = random.Random(6)
        for k in range(0, 11):
            for _ in range(5):
                v = rand_leaves(rng, k, P_FAIR)
                L = Leaves(v)
                self.assertEqual(g.eval_full(L), ref_value(v))
                self.assertEqual(L.reads, 2 ** k)


class TestQ7(unittest.TestCase):
    def test_figure(self):
        L = Leaves(T1)
        self.assertEqual(g.eval_left_first(L), (0, 4))
        self.assertEqual(L.reads, 4)

    def test_random(self):
        rng = random.Random(7)
        for k in range(0, 11):
            for _ in range(5):
                v = rand_leaves(rng, k, P_FAIR)
                L = Leaves(v)
                val, reads = g.eval_left_first(L)
                self.assertEqual(val, ref_value(v))
                self.assertEqual(reads, L.reads)

    def test_worst_case(self):
        self.assertEqual(g.worst_case(0, 1), [1])
        self.assertEqual(g.worst_case(1, 0), [1, 1])
        for k in range(0, 12):
            for v in (0, 1):
                W = g.worst_case(k, v)
                self.assertEqual(len(W), 2 ** k)
                self.assertEqual(ref_value(W), v)
                L = Leaves(W)
                self.assertEqual(g.eval_left_first(L), (v, 2 ** k))


class TestQ8(unittest.TestCase):
    def test_small(self):
        random.seed(80)
        for _ in range(20):
            self.assertEqual(g.eval_random(Leaves([0, 0])), (1, 1))
            self.assertEqual(g.eval_random(Leaves([1, 1])), (0, 2))

    def test_both_orders_used(self):
        random.seed(81)
        seen = {g.eval_random(Leaves([0, 1]))[1] for _ in range(100)}
        self.assertEqual(seen, {1, 2})

    def test_random(self):
        random.seed(82)
        rng = random.Random(8)
        for k in range(0, 11):
            for _ in range(5):
                v = rand_leaves(rng, k, P_FAIR)
                L = Leaves(v)
                val, reads = g.eval_random(L)
                self.assertEqual(val, ref_value(v))
                self.assertEqual(reads, L.reads)

    def test_beats_left_first_on_its_worst_case(self):
        random.seed(83)
        k = 12                                   # n = 4096
        for v in (0, 1):
            W = g.worst_case(k, v)
            avg = sum(g.eval_random(Leaves(W))[1] for _ in range(40)) / 40
            self.assertLess(avg, 0.5 * 2 ** k, avg)


class TestQ9(unittest.TestCase):
    def test_values(self):
        expected = [(1, 1), (1.5, 2), (2.75, 3), (4.375, 5.5), (7.6875, 8.75)]
        for k, (a, b) in enumerate(expected):
            got = g.read_bounds(k)
            self.assertAlmostEqual(got[0], a)
            self.assertAlmostEqual(got[1], b)

    def test_bound_holds_empirically(self):
        random.seed(90)
        k = 8
        a, b = g.read_bounds(k)
        for v in (0, 1):
            W = g.worst_case(k, v)
            avg = sum(g.eval_random(Leaves(W))[1] for _ in range(300)) / 300
            self.assertLessEqual(avg, 1.1 * max(a, b), avg)


class TestQ10(unittest.TestCase):
    def test_budget(self):
        random.seed(100)
        self.assertIsNone(g.eval_budget(Leaves([1, 1]), 1))
        self.assertEqual(g.eval_budget(Leaves([1, 1]), 2), 0)
        self.assertIsNone(g.eval_budget(Leaves([0, 0, 0, 0]), 1))
        self.assertEqual(g.eval_budget(Leaves([0, 0, 0, 0]), 2), 0)
        for _ in range(30):
            L = Leaves(g.worst_case(6, 1))
            r = g.eval_budget(L, 10)
            self.assertLessEqual(L.reads, 11)           # stops as soon as the budget is exceeded
            self.assertIn(r, (None, 1))

    def test_budget_large_is_exact(self):
        random.seed(101)
        rng = random.Random(10)
        for k in range(0, 9):
            v = rand_leaves(rng, k, P_FAIR)
            self.assertEqual(g.eval_budget(Leaves(v), 2 ** k), ref_value(v))

    def test_monte_carlo(self):
        random.seed(102)
        rng = random.Random(11)
        for k in range(0, 11):
            for _ in range(5):
                v = rand_leaves(rng, k, P_FAIR)
                L = Leaves(v)
                self.assertEqual(g.eval_monte_carlo(L, 20), ref_value(v))
                a, b = g.read_bounds(k)
                self.assertLessEqual(L.reads, 20 * (2 * max(a, b) + 1))

    def test_monte_carlo_budget(self):
        """eval_monte_carlo must call eval_budget with budget B = 2 max(a_k, b_k), at most t times."""
        random.seed(103)
        rng = random.Random(12)
        real = g.eval_budget
        budgets = []

        def spy(leaves, budget):
            budgets.append(budget)
            return real(leaves, budget)

        g.eval_budget = spy
        try:
            for k in range(0, 9):
                for _ in range(3):
                    budgets.clear()
                    v = rand_leaves(rng, k, P_FAIR)
                    self.assertEqual(g.eval_monte_carlo(Leaves(v), 20), ref_value(v))
                    self.assertTrue(1 <= len(budgets) <= 20, len(budgets))
                    B = 2 * max(g.read_bounds(k))
                    for b in budgets:
                        self.assertAlmostEqual(b, B, msg=f"k={k}: budget {b} instead of B = {B}")
        finally:
            g.eval_budget = real

    def test_monte_carlo_all_fail(self):
        """If every call to eval_budget fails, eval_monte_carlo makes exactly t calls and returns 1."""
        real = g.eval_budget
        calls = []

        def always_fail(leaves, budget):
            calls.append(budget)
            return None

        g.eval_budget = always_fail
        try:
            self.assertEqual(g.eval_monte_carlo(Leaves([1, 1, 0, 1]), 7), 1)
            self.assertEqual(len(calls), 7)
        finally:
            g.eval_budget = real


if __name__ == '__main__':
    unittest.main(verbosity=2)
